import os, json, re

# Load all demo pairs from harness log
d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
if not d:
    print("RLM_SESSION_DIR not found")
    # Try alternate paths
    for base in ['/' + os.environ.get('HOME', ''), '/home/USER']:
        c = os.path.join(base, '.cache', 'rlm-sessions')
        if os.path.isdir(c):
            import glob
            for fname in glob.glob(os.path.join(c, '*.jsonl')):
                g = open(fname).read()
                m = re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', g)
                for match in m:
                    print(f"Found: {match.groups()}")
                break
    exit()

t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Loaded grids from harness log:")
for k, v in G.items():
    print(f"  {k}: {len(v)}x{len(v[0]) if v else 0}")
